-- Minutes retain the work-date offset past midnight, as in attendance record grammar.
-- console-gate: audited-table attendance_overtime_approvals
CREATE TABLE attendance_overtime_approvals (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    org_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT,
    employee_id UUID NOT NULL,
    work_date DATE NOT NULL,
    from_minutes INTEGER NOT NULL CHECK (from_minutes BETWEEN 0 AND 2879),
    to_minutes INTEGER NOT NULL CHECK (to_minutes > from_minutes AND to_minutes <= 2880),
    approver_employee_id UUID NOT NULL,
    method_code TEXT NOT NULL,
    evidence JSONB NOT NULL CHECK (jsonb_typeof(evidence) = 'array'),
    recorded_by UUID NOT NULL,
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    cancels_id UUID,
    PRIMARY KEY (id, org_id),
    UNIQUE (org_id, cancels_id),
    UNIQUE (id, org_id, employee_id, work_date, from_minutes, to_minutes),
    FOREIGN KEY (employee_id, org_id) REFERENCES employees(id, org_id) ON DELETE RESTRICT,
    FOREIGN KEY (approver_employee_id, org_id) REFERENCES employees(id, org_id) ON DELETE RESTRICT,
    FOREIGN KEY (recorded_by, org_id) REFERENCES users(id, org_id) ON DELETE RESTRICT,
    FOREIGN KEY (cancels_id, org_id, employee_id, work_date, from_minutes, to_minutes)
        REFERENCES attendance_overtime_approvals(id, org_id, employee_id, work_date, from_minutes, to_minutes) ON DELETE RESTRICT,
    CHECK (cancels_id IS NULL OR cancels_id <> id)
);
CREATE INDEX attendance_overtime_approvals_day_idx ON attendance_overtime_approvals (org_id, employee_id, work_date);
ALTER TABLE attendance_overtime_approvals ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance_overtime_approvals FORCE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON attendance_overtime_approvals
    USING (org_id = NULLIF(current_setting('app.current_org', true), '')::uuid)
    WITH CHECK (org_id = NULLIF(current_setting('app.current_org', true), '')::uuid);
REVOKE ALL ON attendance_overtime_approvals FROM PUBLIC, console_rt;
GRANT SELECT, INSERT ON attendance_overtime_approvals TO console_rt;

CREATE FUNCTION attendance_overtime_approval_check() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM system_reason_codes()
                   WHERE domain = 'overtime_approval_method' AND code = NEW.method_code) THEN
        RAISE EXCEPTION 'overtime approval method must be chosen' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (SELECT 1 FROM attendance_overtime_approvals
                WHERE org_id = NEW.org_id AND id = NEW.cancels_id AND cancels_id IS NOT NULL) THEN
        RAISE EXCEPTION 'an overtime cancellation cannot be cancelled' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER trg_attendance_overtime_approvals_check BEFORE INSERT ON attendance_overtime_approvals
    FOR EACH ROW EXECUTE FUNCTION attendance_overtime_approval_check();
CREATE FUNCTION attendance_overtime_immutable() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'overtime evidence is append-only' USING ERRCODE = '55000';
END $$;
CREATE TRIGGER trg_attendance_overtime_approvals_append_only BEFORE UPDATE OR DELETE ON attendance_overtime_approvals
    FOR EACH ROW EXECUTE FUNCTION attendance_overtime_immutable();
COMMENT ON TABLE attendance_overtime_approvals IS 'Approval evidence, never a pay gate; retain through EMPLOYMENT_RECORD_RETENTION_YEARS after completion.';
COMMENT ON COLUMN attendance_overtime_approvals.id IS 'pd:none — evidence identifier';
COMMENT ON COLUMN attendance_overtime_approvals.org_id IS 'pd:none — tenant scope';
COMMENT ON COLUMN attendance_overtime_approvals.employee_id IS 'pd:personal — worker';
COMMENT ON COLUMN attendance_overtime_approvals.work_date IS 'pd:personal — local work date';
COMMENT ON COLUMN attendance_overtime_approvals.from_minutes IS 'pd:personal — approved start minute';
COMMENT ON COLUMN attendance_overtime_approvals.to_minutes IS 'pd:personal — approved end minute';
COMMENT ON COLUMN attendance_overtime_approvals.approver_employee_id IS 'pd:personal — named approver';
COMMENT ON COLUMN attendance_overtime_approvals.method_code IS 'pd:personal — explicit approval method';
COMMENT ON COLUMN attendance_overtime_approvals.evidence IS 'pd:personal — attendance evidence array';
COMMENT ON COLUMN attendance_overtime_approvals.recorded_by IS 'pd:personal — recording account';
COMMENT ON COLUMN attendance_overtime_approvals.recorded_at IS 'pd:none — recorded timestamp';
COMMENT ON COLUMN attendance_overtime_approvals.cancels_id IS 'pd:none — original evidence retained by cancellation';

