ALTER TABLE attendance_exceptions ADD CONSTRAINT attendance_exceptions_org_unit_fk
    FOREIGN KEY (org_id, org_unit_id) REFERENCES org_units(org_id, id) ON DELETE RESTRICT NOT VALID;
ALTER TABLE attendance_exceptions VALIDATE CONSTRAINT attendance_exceptions_org_unit_fk;
CREATE UNIQUE INDEX attendance_exceptions_excess_window_idx
    ON attendance_exceptions (org_id, employee_id, work_date, kind, from_minutes, to_minutes)
    WHERE from_minutes IS NOT NULL AND kind IN ('UNAPPROVED_OVERTIME', 'HOLIDAY_WORK');
CREATE INDEX attendance_exceptions_due_idx ON attendance_exceptions (org_id, due_on) WHERE status = 'OPEN';

-- Compare the complete row so new evidence cannot ride the legacy status-only transition.
CREATE OR REPLACE FUNCTION attendance_exception_resolution_only()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.status <> 'OPEN' OR NEW.status <> 'RESOLVED'
       OR (to_jsonb(NEW) - 'status') IS DISTINCT FROM (to_jsonb(OLD) - 'status') THEN
        RAISE EXCEPTION 'attendance exception only permits OPEN to RESOLVED transition' USING ERRCODE = '25006';
    END IF;
    RETURN NEW;
END $$;

ALTER TABLE attendance_exception_resolutions ADD COLUMN reason_code TEXT;
ALTER TABLE attendance_exception_resolutions ADD COLUMN evidence JSONB CHECK (evidence IS NULL OR jsonb_typeof(evidence) = 'array');
ALTER TABLE attendance_exception_resolutions ADD COLUMN worker_notice_via TEXT CHECK (worker_notice_via IS NULL OR worker_notice_via IN ('IN_APP', 'WRITTEN'));
ALTER TABLE attendance_exception_resolutions ADD COLUMN worker_notified_on DATE;
ALTER TABLE attendance_exception_resolutions ADD COLUMN superseding_entry_id UUID;
ALTER TABLE attendance_exception_resolutions DROP CONSTRAINT attendance_exception_resolutions_action_check;
ALTER TABLE attendance_exception_resolutions ADD CONSTRAINT attendance_exception_resolutions_action_check
    CHECK (action IN ('CONFIRM', 'APPROVE_OVERTIME', 'POST_APPROVAL', 'NOT_WORK', 'RECORD_CORRECTION', 'PAID_OVER_CAP')) NOT VALID;
ALTER TABLE attendance_exception_resolutions VALIDATE CONSTRAINT attendance_exception_resolutions_action_check;
