COMMENT ON COLUMN attendance_exceptions.workplace_id IS 'pd:personal — worker scope workplace';
COMMENT ON COLUMN attendance_exceptions.org_unit_id IS 'pd:personal — worker scope unit';
COMMENT ON COLUMN attendance_exception_resolutions.reason_code IS 'pd:personal — disposition reason';
COMMENT ON COLUMN attendance_exception_resolutions.evidence IS 'pd:personal — disposition evidence';
COMMENT ON COLUMN attendance_exception_resolutions.worker_notice_via IS 'pd:personal — app or written worker notice';
